      seoTitle: "《孟子·梁惠王下》1B.6：王顾左右而言他与政治问责",
      seoDescription: "孟子用层层设问把责任逼回齐宣王：若朋友失职要弃，法官失职要黜，那么四境不治时，最高责任就不能再被转移。",
      readingQuestion: "为什么孟子要让齐宣王“顾左右而言他”？",
