      whyItMatters: "这章极适合承接“王顾左右而言他”“政治问责”“accountability in Mencius”一类搜索，同时能强化整站政治责任主题。",
      citationAngle: "不要把它只当成机智讽刺。孟子这里不是赢口舌，而是在演示如何通过类比，把抽象责任落实到最高权力中心。",
