      seoDescription: "In answering Xu Xing, Mencius is not despising manual labor. He is explaining why education, judgment, and governance cannot be replaced by the shallow equality of universal self-sufficient farming.",
      readingQuestion: "Why does Mencius defend the line that those who labor with their minds govern others?",
