      seoTitle: "《孟子·滕文公下》3B.2：富贵不能淫，贫贱不能移，威武不能屈",
      seoDescription: "孟子反对把纵横家的威势当成“大丈夫”。真正的大丈夫，不是让诸侯害怕的人，而是在得志与不得志两种处境中都不失其道的人。",
