      seoDescription: "Mencius refuses to treat the swagger of political persuaders as greatness. The true great person keeps the way under wealth, poverty, and coercive force alike.",
      readingQuestion: "Why does Mencius deny that sheer geopolitical intimidation makes someone a great person?",
