      seoTitle: "Mencius 4A.1: virtue alone is not enough, law alone cannot run itself",
      seoDescription: "Mencius rejects both sentiment without institutions and institutions without moral force. Real government joins benevolent intent, inherited standards, and executable order in one chain.",
      readingQuestion: "Why does Mencius say that virtue alone is not enough for government and laws cannot move by themselves?",
      directAnswer: "Because good intentions without institutions never reach the people, while institutions without people and principles capable of carrying them do not execute themselves. Government must solve both direction and implementation.",
