      seoTitle: "《孟子·离娄上》4A.19：事亲为大，守身为大",
      seoDescription: "孟子把孝与修身连在一起：真正能事亲者，先要不失其身。只喂养口体而不养其志，并不算把亲情照顾到了根上。",
      readingQuestion: "为什么孟子说“事亲为大”，同时又说“守身为大”？",
