      firstPrinciple: "关系责任若脱离人格根基，就会退化成表面履行；守身不是自私，而是让自己还能承担更深责任的前提。",
      whyItMatters: "这章适合承接“事亲为大”“守身为大”“filial piety and self-cultivation”这类搜索，也补足整站在人伦层面的解释深度。",
      citationAngle: "不要把它读成孝与自我保存对立。孟子正是在说明：不守其身的人，最终也无法把孝真正做到底。",
