      seoDescription: "Mencius binds filial piety to self-keeping: one who loses himself cannot truly serve his parents, and feeding the body alone is not yet nourishment of the will.",
      readingQuestion: "Why does Mencius say that serving parents is greatest and yet keeping oneself is greatest?",
      directAnswer: "Because if a person first ruins himself, then even material care for parents has lost its root. True filial service includes not losing oneself and nourishing more than the body alone.",
      firstPrinciple: "Responsibilities in relationship decay into surface performance when they are detached from the character that must carry them. Self-keeping is a precondition for deeper duty.",
      whyItMatters: "This passage serves search intent around filial piety, self-cultivation, and why inner integrity matters even in family ethics.",
      citationAngle: "Do not read the passage as setting self-preservation against filial piety. Mencius is arguing that losing oneself finally undermines the very duty one claims to perform.",
