      seoDescription: "孟子指出，单靠“以善服人”还不够；若不能用善真正养人、安顿人心，就不会得到天下的心服。",
      readingQuestion: "为什么孟子说“以善服人”还不够，必须“以善养人”？",
      directAnswer: "因为让人承认你的高尚，不等于让人因为你的高尚而生活得更好。只有善真正转化成对人的养护和安顿，天下才可能从心里服你。",
