      seoTitle: "Mencius 4B.16: goodness must nourish people, not merely impress them",
      seoDescription: "Mencius says that excellence alone cannot subdue people. Only when goodness actually nourishes human life can it win the world's sincere submission.",
      readingQuestion: "Why does Mencius say that goodness must nourish people rather than merely subdue them?",
      directAnswer: "Because admiring someone's excellence is not the same as being sustained by it. Only when moral excellence becomes real nourishment for people's condition can the world submit from the heart.",
