      seoDescription: "Mencius uses spring water to explain rooted learning and character: what has a source advances step by step and reaches the seas, unlike rainwater that swells briefly and dries away.",
      readingQuestion: "Why does Mencius use spring water to describe the superior person's way?",
      directAnswer: "Because what is truly dependable has source, continuity, and sequence. Noise without a source can look full for a moment, but it vanishes quickly; rooted growth keeps flowing until it becomes vast.",
