      firstPrinciple: "成长必须先允许自己被真实标准刺痛；没有羞耻感，聪明容易变成自我遮蔽，而不是自我提升。",
      whyItMatters: "这章适合承接“羞耻感”“不耻不若人”“sense of shame in Mencius”这类搜索，也能补强四端与修身主题。",
