      seoDescription: "Mencius gives shame a central role: the danger is not merely being inferior for a time, but no longer feeling that inferiority as something needing correction.",
      readingQuestion: "Why does Mencius say that the sense of shame is of great importance?",
      directAnswer: "Because shame is not decorative emotion. It is the power that returns a person from clever self-justification to real difference. Without it, there is little motive left for genuine improvement.",
