      seoDescription: "孟子把人与道的先后次序说得很清楚：天下有道时，道与身一起出现；天下无道时，应当让身退去而守住道，而不是反过来拿道去殉人。",
      readingQuestion: "为什么孟子说，天下无道时要“以身殉道”？",
