      firstPrinciple: "真正的原则，不是有利时才拿来装点自己；它恰恰在不利时决定你愿意放弃什么，来证明它不是假的。",
      whyItMatters: "这章很适合承接“以身殉道”“principle and survival”“integrity in disorder”这类搜索，是整站关于道义与人格边界的重要页。",
      citationAngle: "不要把这章读成盲目殉难。孟子不是歌颂死亡本身，而是在说明：当道与身发生根本冲突时，不能反过来拿道去迁就人情和权势。",
