      seoDescription: "Mencius is not absolutizing childbirth in isolation. Through Shun's marriage he is asking how to judge when the continuation of familial duty and ritual form come into tension.",
      readingQuestion: "Why does Mencius say that among the forms of unfilial conduct, having no posterity is the greatest?",
