      readingQuestion: "为什么孟子说逢蒙杀羿，羿也有罪？",
      directAnswer: "因为他在追问责任链：逢蒙固然该罪，但若一个人把足以伤人的能力毫无保留地交给德性不足的人，自己也不是完全无责。传授不是只看技术成熟，还要看人格边界。",
      firstPrinciple: "能力的传递从来不是中性的；把强力工具交到谁手里，本身就是道德判断的一部分。",
