      firstPrinciple: "成熟不是逃离身体，而是让人的全部天赋结构——包括形与色——被正确实现出来。",
      whyItMatters: "这章适合承接“践形”“形色天性”“Mencius on embodiment”这类搜索，是性善主题向身体性延伸的重要页面。",
