      seoDescription: "孟子把做官的动机讲得很细：做官本不该只是为贫，但人在某些情境下也可以因贫入仕，关键在于不因此扭曲道与分寸。",
      readingQuestion: "为什么孟子说“仕非为贫也，而有时乎为贫”？",
      directAnswer: "因为理想上，做官不是为了混口饭，而是为了行道；但人在现实里也会遇到贫困压力。孟子允许这种现实入口，却要求人仍守住分寸：可以因贫入仕，不可以因贫卖道。",
      firstPrinciple: "动机判断不能假装现实压力不存在，但也不能让现实压力取消原则边界。",
