      seoDescription: "孟子用巡狩与述职标准说明，政治评价不能只看扩张战绩，而要看土地、田野、老人、贤者是否真的被安顿，这才是王道尺度。",
      readingQuestion: "为什么孟子把五霸称为三王之罪人？",
      directAnswer: "因为五霸式政治把秩序的尺度往下拉了：更看重力量与控制，而不是百姓安顿、人伦修明与贤者在位。孟子要恢复的是另一种考核标准——看一个政体进到其疆内时，到底见到什么。",
