      readingQuestion: "Why does Mencius think a small state practicing kingly rule is not simply doomed before larger enemies?",
      directAnswer: "Because true kingly rule is not expansion for its own sake. It acts to vindicate the harmed and answer for the voiceless. That changes how political force is interpreted by the wider world.",
