      seoTitle: "《孟子·离娄上》4A.28：天下归己若草芥，此之谓大孝",
      seoDescription: "孟子把舜的伟大先落在事亲上：不是先说天下归之，而是先说尽事亲之道。能把父子之伦安顿好，天下的归附反倒成了次要结果。",
      readingQuestion: "为什么孟子说，舜之所以伟大，根本在于“大孝”？",
