      seoDescription: "Mencius locates Shun's greatness not first in receiving the world, but in exhausting the way of serving his parents until family order could truly stand.",
      readingQuestion: "Why does Mencius say that Shun's greatness rests fundamentally in great filiality?",
      directAnswer: "Because for Mencius a person who cannot set the nearest human relationship right is not yet fit to be fully human. Shun first fulfilled the way of serving his parents, and only then did wider order radiate outward.",
