      seoTitle: "《孟子·离娄下》4B.13：送死为什么比养生更当大事",
      seoDescription: "孟子不是贬低奉养父母，而是指出真正见大处，常在死亡面前能否尽其道。送死之礼，检验一个人是否真把亲亲与敬重落实到底。",
      readingQuestion: "为什么孟子说，送死才“可以当大事”？",
