      seoDescription: "Mencius is not belittling care for living parents. He shows that death tests whether reverence and responsibility are carried through where evasion ends.",
      readingQuestion: "Why does Mencius say that seeing parents to the end in death is what may count as the great thing?",
      directAnswer: "Because daily support can become routine, while death brings grief, reverence, and full responsibility into the open. Funeral duty reveals whether one will carry the relation through to its most demanding end.",
