      seoDescription: "仲子能拒不义之齐国，孟子却说这只是箪食豆羹之义；若更大的亲戚、君臣、上下关系全乱了，小处守得再紧，也不能抵掉大处失衡。",
      readingQuestion: "为什么孟子说，拒绝不义之国还只是“小者之义”？",
