      seoDescription: "孟子拒答滕更，不是因为问题本身不能问，而是因为发问姿态先错了：若拿身份、资历、旧劳来压人，求教就已经被权势污染。",
      readingQuestion: "为什么孟子说，挟贵、挟贤、挟长、挟功劳而问，自己都不答？",
