      whyItMatters: "这章适合承接“往者不追，来者不拒”“教育与接纳”“admission and reform in Mencius”这类搜索，也能直接补强本站 method 页面。",
      citationAngle: "不要把它读成对品行完全无要求。孟子不是纵容偷窃，而是把门槛放在此刻来者的求学之心，而不是把教育先变成审判。",
