      seoDescription: "When suspicion falls on his followers, Mencius defends a teaching principle: do not pursue the learner's past without end, and do not refuse those who arrive ready to learn.",
      readingQuestion: "Why does Mencius keep the rule of not pursuing the past and not rejecting those who come, even under suspicion?",
      directAnswer: "Because if education is captured first by suspicion, learning is blocked before it starts. When someone truly comes with the heart to learn, the teacher's first task is reception and guidance rather than retroactive prosecution.",
      firstPrinciple: "Teaching begins from a person's present turn toward what is right, not from endless pursuit of the past. Without such an entry point, reform cannot begin.",
